// ==UserScript==
// @name        Disable disablepictureinpicture
// @version     2.0.0
// @description Remove disablePictureInPicture attribute from video elements, and other client-side workarounds against Picture-in-Picture mode.
// @author      darcien
// @match       https://nicochannel.jp/*
// @match       https://qlover.jp/*
// @inject-into page
// @homepageURL https://github.com/darcien/userscripts/tree/master/disable-disablepictureinpicture
// @downloadURL https://github.com/darcien/userscripts/raw/master/disable-disablepictureinpicture/dist/disable-disablepictureinpicture.user.js
// ==/UserScript==

(function(){"use strict";const ATTRIBUTE="disablepictureinpicture",removalCounts=new WeakMap,FORWARD_INTERVAL_MS=250,isElement=node=>node.nodeType===Node.ELEMENT_NODE,isVideo=node=>node.nodeName==="VIDEO";function enablePictureInPicture(video){if(!video.hasAttribute(ATTRIBUTE))return;const count=(removalCounts.get(video)??0)+1;if(removalCounts.set(video,count),count>20){count===20+1&&console.warn(`[disable-disablepictureinpicture] Stopped on this video: the page added ${ATTRIBUTE} again 20 times.`,video);return}video.removeAttribute(ATTRIBUTE)}function enablePictureInPictureIn(root){isVideo(root)&&enablePictureInPicture(root);for(const video of root.querySelectorAll(`video[${ATTRIBUTE}]`))enablePictureInPicture(video)}function lockDisablePictureInPictureSetter(){const prototype=HTMLVideoElement.prototype,descriptor=Object.getOwnPropertyDescriptor(prototype,"disablePictureInPicture"),set=descriptor?.set;set&&Object.defineProperty(prototype,"disablePictureInPicture",{...descriptor,set(_value){set.call(this,!1)}})}function preventExitOnEnter(){document.documentElement.addEventListener("enterpictureinpicture",event=>event.stopPropagation())}function forwardHoverToCoveredVideos(){let lastForwardTime=-1/0;document.addEventListener("mousemove",event=>{const target=event.target;if(!event.isTrusted||!target||isVideo(target)||!document.body.contains(target)||event.timeStamp-lastForwardTime<FORWARD_INTERVAL_MS)return;const{clientX:x,clientY:y}=event;for(const video of document.querySelectorAll("video")){const rect=video.getBoundingClientRect();if(x>rect.left&&x<rect.right&&y>rect.top&&y<rect.bottom){lastForwardTime=event.timeStamp,video.dispatchEvent(new MouseEvent("mousemove",{clientX:x,clientY:y,screenX:event.screenX,screenY:event.screenY,button:event.button,buttons:event.buttons,altKey:event.altKey,ctrlKey:event.ctrlKey,metaKey:event.metaKey,shiftKey:event.shiftKey}));return}}},!0)}function observeVideos(){new MutationObserver(mutations=>{for(const mutation of mutations){if(mutation.type==="attributes"){isVideo(mutation.target)&&enablePictureInPicture(mutation.target);continue}for(const node of mutation.addedNodes)isElement(node)&&enablePictureInPictureIn(node)}}).observe(document,{childList:!0,subtree:!0,attributes:!0,attributeFilter:[ATTRIBUTE]})}lockDisablePictureInPictureSetter(),preventExitOnEnter(),forwardHoverToCoveredVideos(),enablePictureInPictureIn(document),observeVideos()})();
